def transform(grid):
    """Fill gaps between repeated foreground markers within each row with 2."""
    from collections import Counter

    flat = [v for row in grid for v in row]
    background = Counter(flat).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        markers = [c for c, value in enumerate(row) if value != background]
        if len(markers) >= 2:
            for c in range(markers[0], markers[-1] + 1):
                if row[c] == background:
                    out[r][c] = 2
    return out
